        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary: #1a1a2e;
            --secondary: #16213e;
            --accent: #e94560;
            --gold: #d4af37;
            --silver: #a8a8a8;
            --bronze: #cd7f32;
            --text: #eaeaea;
            --text-muted: #9a9a9a;
            --card-bg: #0f3460;
        }

        body {
            font-family: 'Georgia', serif;
            background: var(--primary);
            color: var(--text);
            line-height: 1.7;
            min-height: 100vh;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 2rem;
        }

        header {
            text-align: center;
            padding: 4rem 2rem;
            background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
            border-bottom: 3px solid var(--gold);
