            font-size: 2rem;
            color: var(--gold);
            margin-bottom: 2rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px solid var(--accent);
            display: inline-block;
        }

        section p {
            margin-bottom: 1.5rem;
            font-size: 1.1rem;
            color: var(--text);
            max-width: 900px;
        }

        /* Chart Containers */
        .chart-container {
            background: var(--secondary);
            border-radius: 12px;
            padding: 2rem;
            margin: 2rem 0;
            border: 1px solid rgba(255,255,255,0.1);
