        .chart-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 2rem;
        }

        /* Top Composers Table */
        .composer-table {
            width: 100%;
            border-collapse: collapse;
            margin: 2rem 0;
            background: var(--secondary);
            border-radius: 8px;
            overflow: hidden;
        }

        .composer-table th,
        .composer-table td {
            padding: 1rem 1.5rem;
            text-align: left;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }

        .composer-table th {
            background: var(--card-bg);
            color: var(--gold);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-size: 0.85rem;
        }

        .composer-table tr:hover td {
            background: rgba(212, 175, 55, 0.1);
        }

        .rank-badge {
            display: inline-block;
            width: 30px;
            height: 30px;
            line-height: 30px;
            text-align: center;
            border-radius: 50%;
            font-weight: bold;
            font-size: 0.9rem;
        }

        .rank-1 { background: var(--gold); color: var(--primary); }
        .rank-2 { background: var(--silver); color: var(--primary); }
        .rank-3 { background: var(--bronze); color: var(--primary); }
        .rank-other { background: var(--card-bg); color: var(--text); }

        /* Decade Cards */
        .decade-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 1.5rem;
            margin: 2rem 0;
        }

        .decade-card {
            background: var(--card-bg);
            border-radius: 8px;
            padding: 1.5rem;
            border-left: 4px solid var(--accent);
        }

