            font-size: 1.5rem;
            color: var(--gold);
            margin-bottom: 1rem;
        }

        .decade-stat {
            display: flex;
            justify-content: space-between;
            padding: 0.5rem 0;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }

        .decade-stat:last-child {
            border-bottom: none;
        }

        .decade-stat-value {
            font-weight: 600;
            color: var(--accent);
        }

        /* Era Sections */
