            display: flex;
            gap: 1.5rem;
            padding: 1.5rem;
            background: var(--secondary);
            border-radius: 8px;
            margin: 1rem 0;
            border-left: 3px solid var(--gold);
        }

        .milestone-year {
            font-size: 2rem;
            font-weight: 700;
            color: var(--gold);
            font-family: 'Arial', sans-serif;
