        }

        .milestone-content h4 {
            color: var(--text);
            margin-bottom: 0.3rem;
        }

        .milestone-content p {
            color: var(--text-muted);
            font-size: 0.95rem;
            margin: 0;
        }

        /* Takeaways */
        .takeaway {
            display: flex;
            gap: 1rem;
            padding: 1.5rem;
            background: var(--secondary);
            border-radius: 8px;
            margin: 1rem 0;
        }

        .takeaway-number {
            background: var(--accent);
